import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        Set<Integer> lucky = new HashSet<>();
        for (int x = 0; x <= 9; x++) {
            for (int y = x; y <= 9; y++) {
                List<Integer> digits = new ArrayList<>();
                if (x == y) {
                    digits.add(x);
                } else {
                    digits.add(x);
                    digits.add(y);
                }
                generateNumbers(digits, n, lucky);
            }
        }
        System.out.println(lucky.size());
    }

    private static void generateNumbers(List<Integer> digits, int n, Set<Integer> lucky) {
        for (int d : digits) {
            if (d == 0) continue;
            if (d > n) continue;
            lucky.add(d);
            generateNumbersHelper(digits, d, n, lucky);
        }
    }

    private static void generateNumbersHelper(List<Integer> digits, int current, int n, Set<Integer> lucky) {
        for (int d : digits) {
            int next = current * 10 + d;
            if (next > n) continue;
            if (!lucky.contains(next)) {
                lucky.add(next);
                generateNumbersHelper(digits, next, n, lucky);
            }
        }
    }
}
