import java.util.*;

public class Main {
    static int n;
    static Set<Integer> set = new HashSet<>();

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        for (int x = 0; x <= 9; x++) {
            for (int y = x; y <= 9; y++) {
                generate(x, y);
            }
        }
        System.out.println(set.size());
    }

    static void generate(int x, int y) {
        for (int len = 1; len <= String.valueOf(n).length(); len++) {
            if (len == 1) {
                if (x != 0 && x <= n) set.add(x);
                if (y != 0 && y <= n) set.add(y);
            } else {
                if (x == 0 && y == 0) continue;
                List<Integer> digits = new ArrayList<>();
                if (x != 0) digits.add(x);
                if (y != 0) digits.add(y);
                if (digits.isEmpty()) continue;
                int first = digits.get(0);
                if (first > n) continue;
                int[] rest = new int[len - 1];
                Arrays.fill(rest, x);
                int num = first;
                for (int i = 0; i < len - 1; i++) {
                    num = num * 10 + rest[i];
                }
                if (num <= n) set.add(num);
                if (digits.size() == 2) {
                    for (int i = 0; i < len - 1; i++) {
                        for (int d : digits) {
                            int[] temp = new int[len - 1];
                            Arrays.fill(temp, x);
                            temp[i] = d;
                            int val = first;
                            for (int j = 0; j < len - 1; j++) {
                                val = val * 10 + temp[j];
                            }
                            if (val <= n) set.add(val);
                        }
                    }
                }
            }
        }
    }
}
